// Regenerates src/editor/luts.generated.ts from assets/luts/*.cube.
// Run with: node --experimental-strip-types scripts/build-luts.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildAtlas, parseCube } from '../src/editor/cube.ts';

const here = dirname(fileURLToPath(import.meta.url));
const lutDir = join(here, '../../../assets/luts');
const ids = ['soft-warm', 'cool-clean', 'muted-film', 'balanced-mono'];

export function generate() {
  const lines = [
    '// Generated by scripts/build-luts.mjs from assets/luts/*.cube. Do not edit.',
    "import type { LookId } from './model.ts';",
    '',
    'export const LUT_ATLAS_BASE64: Readonly<Record<LookId, { readonly size: number; readonly base64: string }>> = {',
  ];
  for (const id of ids) {
    const cube = parseCube(readFileSync(join(lutDir, `${id}.cube`), 'utf8'));
    const b64 = Buffer.from(buildAtlas(cube)).toString('base64');
    lines.push(`  '${id}': { size: ${cube.size}, base64: '${b64}' },`);
  }
  lines.push('};', '');
  return lines.join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(join(here, '../src/editor/luts.generated.ts'), generate());
  console.log('wrote src/editor/luts.generated.ts');
}
